export type CuratedQ = { id: string; day: number; d: number; q: string; o: string[]; a: number; es?: { q: string; o: string[] } };
export const CURATED: Readonly<Record<string, CuratedQ[][]>> = {"HINDUISM":[[{"id":"HINDUISM-s00-01","day":2,"d":1,"q":"In the Mandukya Upanishad, which state of consciousness does the sound M of om (a-u-m) stand for?","o":["the state of waking","the state of dreaming","deep dreamless sleep","the soundless fourth"],"a":2,"es":{"q":"En la Mandukya Upanishad, ¿qué estado de conciencia representa el sonido M de om (a-u-m)?","o":["el estado de vigilia","el estado de soñar","el sueño profundo","el cuarto, sin sonido"]}},{"id":"HINDUISM-s00-02","day":3,"d":1,"q":"The Sanskrit word dharma comes from the verbal root dhṛ. What does that root mean?","o":["to act, to perform","to hold, to uphold","to see, to perceive","to bow, to give way"],"a":1,"es":{"q":"La palabra sánscrita dharma viene de la raíz verbal dhṛ. ¿Qué significa esa raíz?","o":["actuar, llevar a cabo","sostener, sustentar","ver, darse cuenta","inclinarse, ceder"]}},{"id":"HINDUISM-s00-03","day":11,"d":2,"q":"In the Chandogya Upanishad, Uddalaka has his son Shvetaketu dissolve salt in water and then taste it. What is the teaching?","o":["Brahman pervades all, though it cannot be seen","the body must be purified before the self is known","the senses deceive us, so taste cannot be trusted","all things arise from water, the first element"],"a":0,"es":{"q":"En la Chandogya Upanishad, Uddalaka le pide a su hijo Shvetaketu que disuelva sal en agua y luego la pruebe. ¿Cuál es la enseñanza?","o":["Brahman lo impregna todo, aunque no se vea","hay que purificar el cuerpo para conocer el ser","los sentidos engañan; no hay que fiarse del gusto","todo nace del agua, el primero de los elementos"]}},{"id":"HINDUISM-s00-04","day":19,"d":2,"q":"In the Katha Upanishad, Yama offers Nachiketa wealth, long life and kingdoms in place of his third wish. How does Nachiketa respond?","o":["he accepts a kingdom so that he can rule with justice","he asks Yama for a lasting place among the gods","he takes the wealth and gives it away to the poor","he refuses them as fleeting and keeps his question"],"a":3,"es":{"q":"En la Katha Upanishad, Yama le ofrece a Nachiketa riquezas, larga vida y reinos en lugar de su tercer deseo. ¿Cómo responde Nachiketa?","o":["acepta un reino para poder gobernar con justicia","le pide a Yama un lugar eterno entre los dioses","toma las riquezas y las reparte entre los pobres","los rechaza por efímeros y sigue en su pregunta"]}},{"id":"HINDUISM-s00-05","day":16,"d":2,"q":"In Bhagavad Gita 9.26, Krishna says he accepts even a leaf, a flower, a fruit or water. What makes such an offering acceptable to him?","o":["the purity of the priest who presents it","the devotion with which it is given","the rarity and cost of what is brought","the correct Vedic verse recited with it"],"a":1,"es":{"q":"En el Bhagavad Gita 9.26, Krishna dice que acepta incluso una hoja, una flor, una fruta o agua. ¿Qué hace que esa ofrenda le sea aceptable?","o":["la pureza del sacerdote que la da","la devoción con la que se ofrece","lo raro y costoso de lo que se trae","el verso védico correcto que se recita"]}},{"id":"HINDUISM-s00-06","day":10,"d":2,"q":"A student says, 'My true self is my thoughts.' Following Yajnavalkya in the Brihadaranyaka Upanishad ('you cannot think the thinker of thinking'), what is the reply?","o":["thoughts are known, so they are not the knower","thoughts are pure, so they reveal the true self","thoughts are of the mind, so the mind is the self","thoughts see the world, so they are the seer"],"a":0,"es":{"q":"Un estudiante dice: «Mi verdadero ser son mis pensamientos». Siguiendo a Yajnavalkya en la Brihadaranyaka Upanishad («no puedes pensar al pensador del pensar»), ¿cuál es la respuesta?","o":["los pensamientos se conocen; no son quien conoce","los pensamientos son puros y así revelan el ser","los pensamientos son de la mente, y la mente es el ser","los pensamientos ven el mundo; ellos son quien ve"]}}],[{"id":"HINDUISM-s01-01","day":29,"d":1,"q":"In the Ramayana tradition, what does 'hanu' in the name Hanuman refer to?","o":["his tail, set alight in the city of Lanka","his father, Vayu, the god of the wind","his leap across the ocean to find Sita","his jaw, struck by Indra's thunderbolt"],"a":3,"es":{"q":"En la tradición del Ramayana, ¿a qué se refiere «hanu» en el nombre Hanuman?","o":["a su cola, incendiada en la ciudad de Lanka","a su padre, Vayu, el dios del viento","a su salto sobre el océano para hallar a Sita","a su mandíbula, golpeada por el rayo de Indra"]}},{"id":"HINDUISM-s01-02","day":26,"d":1,"q":"Ganesha is often shown holding his own broken tusk. In the best-known popular telling, what did he use it for?","o":["as a pen to write down Vyasa's dictation","as an offering laid down at his father's feet","as a parting gift for his brother Kartikeya","as a stylus to carve the Vedas in stone"],"a":0,"es":{"q":"A Ganesha se le muestra a menudo con su propio colmillo roto en la mano. En el relato popular más conocido, ¿para qué lo usó?","o":["como pluma para escribir lo que dictaba Vyasa","como ofrenda depositada a los pies de su padre","como regalo de despedida para su hermano Kartikeya","como punzón para grabar los Vedas en piedra"]}},{"id":"HINDUISM-s01-03","day":39,"d":2,"q":"In the Valmiki Ramayana, why does King Dasharatha send Rama into fourteen years of exile?","o":["Rama has broken a law and has to be punished","the priests rule that Bharata is the elder son","he is bound by two boons he once promised Kaikeyi","a sage warns that Rama will bring the kingdom harm"],"a":2,"es":{"q":"En el Ramayana de Valmiki, ¿por qué el rey Dasharatha envía a Rama a catorce años de exilio?","o":["Rama violó una ley y tiene que ser castigado","los sacerdotes deciden que Bharata es el mayor","está atado a dos deseos que le prometió a Kaikeyi","un sabio advierte que Rama dañará al reino"]}},{"id":"HINDUISM-s01-04","day":44,"d":2,"q":"In the Ramayana, after Rama refuses to come back from the forest, how does Bharata govern Ayodhya?","o":["as crowned king, as his mother Kaikeyi wished","as regent, with Rama's sandals on the throne","as heir, until his own son could take the throne","as co-ruler, sharing power with Lakshmana"],"a":1,"es":{"q":"En el Ramayana, después de que Rama se niega a volver del bosque, ¿cómo gobierna Bharata Ayodhya?","o":["como rey coronado, como quería su madre Kaikeyi","como regente, con las sandalias de Rama en el trono","como heredero, hasta que su hijo pudiera reinar","como cogobernante, compartiendo el poder con Lakshmana"]}},{"id":"HINDUISM-s01-05","day":82,"d":2,"q":"Holika Dahan, the bonfire lit on the night before Holi, recalls which story?","o":["Sita passing through fire after the war in Lanka","Hanuman setting Lanka ablaze with his burning tail","Krishna swallowing a forest fire to save the herders","Prahlad surviving the fire that burned his aunt"],"a":3,"es":{"q":"Holika Dahan, la hoguera que se enciende la noche antes de Holi, ¿qué historia recuerda?","o":["Sita atraviesa el fuego después de la guerra en Lanka","Hanuman incendia Lanka con su cola en llamas","Krishna se traga un incendio para salvar a los pastores","Prahlad sobrevive al fuego que quemó a su tía"]}},{"id":"HINDUISM-s01-06","day":83,"d":2,"q":"A temple stays open all night on the fourteenth night of the waning moon in late winter. Devotees fast, pour water and milk over a lingam and offer bilva leaves. Which festival is being kept?","o":["Makar Sankranti","Ganesh Chaturthi","Maha Shivaratri","Vasant Panchami"],"a":2,"es":{"q":"Un templo queda abierto toda la noche en la decimocuarta noche de la luna menguante, a fines del invierno. Los devotos ayunan, vierten agua y leche sobre un lingam y ofrecen hojas de bilva. ¿Qué festividad se celebra?","o":["Makar Sankranti","Ganesh Chaturthi","Maha Shivaratri","Vasant Panchami"]}}],[{"id":"HINDUISM-s02-01","day":108,"d":2,"q":"Which sage does tradition name as the seer of the Gayatri mantra (Rig Veda 3.62.10)?","o":["the sage Vasishtha","the sage Vishvamitra","the sage Bharadvaja","the sage Markandeya"],"a":1,"es":{"q":"¿A qué sabio nombra la tradición como el vidente del mantra Gayatri (Rig Veda 3.62.10)?","o":["el sabio Vasishtha","el sabio Vishvamitra","el sabio Bharadvaja","el sabio Markandeya"]}},{"id":"HINDUISM-s02-02","day":130,"d":2,"q":"When in the Hindu calendar is Ekadashi, a common fast day for devotees of Vishnu, kept?","o":["on the full-moon day of every lunar month","on the eleventh day of every solar month","on the new-moon day of each lunar month","on each fortnight's eleventh lunar day"],"a":3,"es":{"q":"¿Cuándo se guarda en el calendario hindú Ekadashi, un día de ayuno común entre los devotos de Vishnu?","o":["el día de luna llena de cada mes lunar","el día once de cada mes del calendario solar","el día de luna nueva de cada mes lunar","el undécimo día lunar de cada quincena"]}},{"id":"HINDUISM-s02-03","day":133,"d":2,"q":"In Hindu temple worship, what does it mean to 'take darshan' of a deity?","o":["to see the deity's image and be seen by it","to walk clockwise around the inner shrine","to receive food that was offered to the deity","to hear the priest recite the deity's names"],"a":0,"es":{"q":"En el culto del templo hindú, ¿qué significa «tomar darshan» de una deidad?","o":["ver la imagen de la deidad y ser visto por ella","caminar en sentido horario alrededor del santuario","recibir comida que se le ofreció a la deidad","escuchar al sacerdote recitar los nombres de la deidad"]}},{"id":"HINDUISM-s02-04","day":128,"d":2,"q":"Bhagavad Gita 17.8–10 sorts food by the three gunas. Which food does it call sattvic?","o":["very pungent, sour, salty, dry food that burns and stings","stale, tasteless food, left over and kept overnight","savory, rich, lasting food that adds life and health","plain, raw, unseasoned food prepared without oil"],"a":2,"es":{"q":"El Bhagavad Gita 17.8–10 clasifica los alimentos según los tres gunas. ¿Qué comida llama sáttvica?","o":["comida muy picante, agria, salada y seca, que quema","comida rancia, insípida, sobrante, de la víspera","comida sabrosa, untuosa y firme, que da vida y salud","comida simple, cruda, sin sazón y preparada sin aceite"]}},{"id":"HINDUISM-s02-05","day":134,"d":2,"q":"Why is pradakshina, walking around a shrine or sacred place, done clockwise?","o":["so that the holy center stays on one's right","so that one's shadow does not fall on the shrine","so that the walker mirrors the waning moon","so that the shrine's guardians are greeted first"],"a":0,"es":{"q":"¿Por qué la pradakshina, caminar alrededor de un santuario o lugar sagrado, se hace en sentido horario?","o":["para que el centro sagrado quede a la derecha","para que la sombra no caiga sobre el santuario","para que quien camina imite a la luna menguante","para saludar primero a los guardianes del santuario"]}},{"id":"HINDUISM-s02-06","day":151,"d":3,"q":"A family checks the panchang every year for the date of Diwali, but always plans Makar Sankranti for mid-January. What makes this possible?","o":["Sankranti is lunar; Diwali is set by the sun","Diwali is moved each year to match the harvest","priests pick a fresh date for Diwali each year","Sankranti is solar; Diwali is set by the moon"],"a":3,"es":{"q":"Una familia consulta cada año el panchang para saber la fecha de Diwali, pero siempre planea Makar Sankranti para mediados de enero. ¿Qué lo hace posible?","o":["Sankranti es lunar; Diwali depende del sol","Diwali se mueve cada año según la cosecha","cada año los sacerdotes fijan otra fecha","Sankranti es solar; Diwali depende de la luna"]}}],[{"id":"HINDUISM-s03-01","day":157,"d":2,"q":"In the Bhagavad Gita, who reports the battlefield dialogue between Krishna and Arjuna to the blind king Dhritarashtra?","o":["Sanjaya, the king's charioteer and aide","Vidura, the king's wise younger half-brother","Bhishma, the grand elder of the Kuru house","Yudhishthira, the eldest of the Pandavas"],"a":0,"es":{"q":"En el Bhagavad Gita, ¿quién le cuenta al rey ciego Dhritarashtra el diálogo entre Krishna y Arjuna en el campo de batalla?","o":["Sanjaya, auriga y consejero del rey","Vidura, el sabio medio hermano del rey","Bhishma, el gran anciano de la casa Kuru","Yudhishthira, el mayor de los Pandava"]}},{"id":"HINDUISM-s03-02","day":171,"d":2,"q":"In Bhagavad Gita 4.7–8, Krishna says he brings himself forth age after age. When does he say this happens?","o":["whenever the Vedas are recited without faith","whenever a world-age ends in fire and flood","whenever dharma declines and adharma rises","whenever a king breaks his oath to a sage"],"a":2,"es":{"q":"En el Bhagavad Gita 4.7–8, Krishna dice que se manifiesta era tras era. ¿Cuándo dice que esto ocurre?","o":["cuando los Vedas se recitan sin ninguna fe","cuando una era termina en fuego y diluvio","cuando el dharma decae y crece el adharma","cuando un rey rompe su juramento a un sabio"]}},{"id":"HINDUISM-s03-03","day":180,"d":2,"q":"Which image does Bhagavad Gita 6.19 use for the steady mind of a yogi in meditation?","o":["a lotus leaf water cannot wet","a lamp in a place with no wind","a tortoise drawing in its limbs","an ocean unmoved by inflowing rivers"],"a":1,"es":{"q":"¿Qué imagen usa el Bhagavad Gita 6.19 para la mente firme de un yogui en meditación?","o":["una hoja de loto que el agua no moja","una lámpara donde no sopla el viento","una tortuga que recoge sus miembros","un océano que los ríos no agitan"]}},{"id":"HINDUISM-s03-04","day":219,"d":3,"q":"In Bhagavad Gita 18.2, what do the wise call tyaga, relinquishment?","o":["giving up actions done out of desire","giving up home to wander as a monk","giving up food and sleep as austerity","giving up the fruits of all actions"],"a":3,"es":{"q":"En el Bhagavad Gita 18.2, ¿a qué llaman los sabios tyaga, el desprendimiento?","o":["a dejar las acciones hechas por deseo","a dejar el hogar y vagar como monje","a dejar comida y sueño como austeridad","a renunciar a los frutos de toda acción"]}},{"id":"HINDUISM-s03-05","day":207,"d":3,"q":"According to Bhagavad Gita 14.6–8, how does tamas bind the embodied self?","o":["by attachment to happiness and knowledge","by heedlessness, laziness and sleep","by attachment to action and its fruits","by fear of death and grief for the dead"],"a":1,"es":{"q":"Según el Bhagavad Gita 14.6–8, ¿cómo ata tamas al ser encarnado?","o":["con apego a la felicidad y al saber","con la negligencia, la pereza y el sueño","con apego a la acción y sus frutos","con miedo a morir y pena por los muertos"]}},{"id":"HINDUISM-s03-06","day":222,"d":3,"q":"A talented musician envies a friend's legal career and wants to copy it, though it suits neither his gifts nor his nature. Which Bhagavad Gita teaching speaks most directly to this?","o":["the self is unborn and undying, so do not grieve","the wise see the same in a priest and in a dog","better one's own dharma, flawed, than another's","work done as an offering (yajna) does not bind"],"a":2,"es":{"q":"Un músico talentoso envidia la carrera de abogado de un amigo y quiere copiarla, aunque no va con sus dones ni con su naturaleza. ¿Qué enseñanza del Bhagavad Gita habla más directamente de esto?","o":["el ser no nace ni muere, así que no te aflijas","el sabio ve lo mismo en un sacerdote y en un perro","mejor el dharma propio, imperfecto, que el ajeno","el trabajo hecho como ofrenda (yajna) no ata"]}}],[{"id":"HINDUISM-s04-01","day":233,"d":3,"q":"the Isha Upanishad's first verse says \"tena tyaktena bhunjitha.\" in its common reading, which takes bhunjitha as \"enjoy,\" what does that phrase tell the reader to do?","o":["renounce the world in order to reach heaven","enjoy the world while gathering more wealth","enjoy the world through renunciation","give up all action and live in the forest"],"a":2,"es":{"q":"el primer verso de la Isha Upanishad dice \"tena tyaktena bhunjitha\". en su lectura común, que entiende bhunjitha como \"disfruta\", ¿qué le pide esa frase al lector?","o":["renunciar al mundo para llegar al cielo","disfrutar del mundo mientras junta más riqueza","disfrutar del mundo a través de la renuncia","dejar toda acción e irse a vivir al bosque"]}},{"id":"HINDUISM-s04-02","day":243,"d":3,"q":"in the Kena Upanishad's story, the gods boast of a victory, and Agni, the fire god, cannot burn a single blade of grass set before him by a mysterious being (a yaksha). what is the story teaching?","o":["the gods' powers come from Brahman, not from the gods themselves","fire is the weakest of the gods, so it was tested first","the gods won their victory by the power of their own sacrifices","Brahman is seen by the eye once the gods have given up their pride"],"a":0,"es":{"q":"en el relato de la Kena Upanishad, los dioses presumen de una victoria, y Agni, el dios del fuego, no logra quemar una sola brizna de hierba que le pone delante un ser misterioso (un yaksha). ¿qué enseña el relato?","o":["los poderes de los dioses vienen de Brahman, no de los dioses mismos","el fuego es el más débil de los dioses, por eso lo probaron primero","los dioses ganaron la victoria por la fuerza de sus propios sacrificios","Brahman se ve con los ojos cuando los dioses dejan de lado su orgullo"]}},{"id":"HINDUISM-s04-03","day":248,"d":3,"q":"a merchant turns down a profitable but dishonest deal so as to keep his word. in the terms of the Katha Upanishad's two paths (1.2.1–2), what has he chosen?","o":["preyas, the pleasant, over shreyas, the good","shreyas, the good, over preyas, the pleasant","artha, prosperity, over dharma, right conduct","kama, desire, over moksha, liberation"],"a":1,"es":{"q":"un comerciante rechaza un negocio rentable pero deshonesto para cumplir su palabra. en los términos de los dos caminos de la Katha Upanishad (1.2.1–2), ¿qué eligió?","o":["preyas, lo agradable, por encima de shreyas, lo bueno","shreyas, lo bueno, por encima de preyas, lo agradable","artha, la prosperidad, por encima de dharma, la recta conducta","kama, el deseo, por encima de moksha, la liberación"]}},{"id":"HINDUISM-s04-04","day":256,"d":3,"q":"in the Mandukya Upanishad, the third quarter of the self, called prajna (\"the knowing one\"), is one mass of knowing, made of bliss. which state is its field?","o":["the state of waking","the state of dreaming","the fourth, turiya","dreamless deep sleep"],"a":3,"es":{"q":"en la Mandukya Upanishad, el tercer cuarto del ser, llamado prajna (\"el que conoce\"), es una sola masa de conocer, hecha de dicha. ¿cuál es su campo?","o":["el estado de estar despierto","el estado de sueño con sueños","el cuarto estado, turiya","el sueño profundo sin sueños"]}},{"id":"HINDUISM-s04-05","day":289,"d":3,"q":"according to Ramanuja's Vishishtadvaita (\"qualified non-dualism\"), how are the world and individual souls related to God?","o":["they are an illusion laid over Brahman, like a snake seen on a rope","they are fully real and exist entirely independent of God","they are a dream of God that ends when God wakes from it","they are real and form God's body, wholly dependent on God"],"a":3,"es":{"q":"según el Vishishtadvaita de Ramanuja (\"no dualismo calificado\"), ¿cómo se relacionan el mundo y las almas individuales con Dios?","o":["son una ilusión sobre Brahman, como la serpiente en la cuerda","son plenamente reales y existen del todo independientes de Dios","son solo un sueño de Dios, que se acaba cuando él despierta","son reales y forman el cuerpo de Dios, dependientes de él"]}},{"id":"HINDUISM-s04-06","day":320,"d":3,"q":"among the Bhagavad Gita's three kinds of gift (17.20–22), which kind is a gift given expecting something in return, or given grudgingly?","o":["sattvic, of clarity and goodness","rajasic, of restless passion","tamasic, of dullness and inertia","daivi, of the divine qualities"],"a":1,"es":{"q":"entre los tres tipos de regalo del Bhagavad Gita (17.20–22), ¿de qué tipo es un regalo dado esperando algo a cambio, o dado de mala gana?","o":["sáttvico, de claridad y bondad","rajásico, de pasión inquieta","tamásico, de torpeza e inercia","daivi, de las cualidades divinas"]}}],[{"id":"HINDUISM-s05-01","day":404,"d":3,"q":"which Upanishad contains the great saying (mahavakya) \"prajnanam brahma,\" \"consciousness is Brahman\"?","o":["the Aitareya Upanishad","the Chandogya Upanishad","the Taittiriya Upanishad","the Mandukya Upanishad"],"a":0,"es":{"q":"¿qué Upanishad contiene la gran sentencia (mahavakya) \"prajnanam brahma\", \"la conciencia es Brahman\"?","o":["la Aitareya Upanishad","la Chandogya Upanishad","la Taittiriya Upanishad","la Mandukya Upanishad"]}},{"id":"HINDUISM-s05-02","day":340,"d":3,"q":"in the Chandogya Upanishad (6.1.4), Uddalaka tells his son Shvetaketu that by knowing one lump of clay, everything made of clay is known. what point is he making?","o":["the world was shaped by the gods as a potter shapes clay","knowing many objects one at a time adds up to knowing all","pots differ only in name; the clay alone is what is real","the clay changes its true nature each time it is shaped"],"a":2,"es":{"q":"en la Chandogya Upanishad (6.1.4), Uddalaka le dice a su hijo Shvetaketu que al conocer un solo terrón de barro se conoce todo lo hecho de barro. ¿qué quiere mostrar?","o":["los dioses dieron forma al mundo como un alfarero al barro","conocer muchas cosas una por una suma hasta conocerlo todo","las vasijas difieren solo en el nombre; lo real es el barro","el barro cambia su verdadera naturaleza cada vez que se moldea"]}},{"id":"HINDUISM-s05-03","day":358,"d":4,"q":"in the Chandogya Upanishad (8.9), why does Indra turn back to Prajapati after being taught that the self is the body seen reflected in water?","o":["he forgot the teaching on his way home and had to hear it again","he saw that such a self would decay and die with the body","Virochana challenged him to a debate that he could not win","the gods refused to accept him as king until he learned more"],"a":1,"es":{"q":"en la Chandogya Upanishad (8.9), ¿por qué Indra vuelve con Prajapati después de que le enseñaron que el ser es el cuerpo reflejado en el agua?","o":["olvidó la enseñanza camino a casa y tuvo que oírla de nuevo","vio que ese ser se deterioraría y moriría junto con el cuerpo","Virochana lo desafió a un debate que él no podía ganar","los dioses no lo aceptaban como rey hasta que aprendiera más"]}},{"id":"HINDUISM-s05-04","day":377,"d":3,"q":"at King Janaka's court in the Brihadaranyaka Upanishad, which woman questions Yajnavalkya about what everything is \"woven\" on?","o":["Maitreyi, his wife","Katyayani, his wife","Apala, a Vedic seer","Gargi Vachaknavi"],"a":3,"es":{"q":"en la corte del rey Janaka, en la Brihadaranyaka Upanishad, ¿qué mujer le pregunta a Yajnavalkya sobre qué está \"tejido\" todo?","o":["Maitreyi, su esposa","Katyayani, su esposa","Apala, una rishika","Gargi Vachaknavi"]}},{"id":"HINDUISM-s05-05","day":393,"d":3,"q":"in the Taittiriya Upanishad (2.1–2.5), which is the innermost of the five sheaths (koshas) of the self?","o":["anandamaya, made of bliss","vijnanamaya, made of insight","manomaya, made of the mind","pranamaya, made of breath"],"a":0,"es":{"q":"en la Taittiriya Upanishad (2.1–2.5), ¿cuál es la más interior de las cinco envolturas (koshas) del ser?","o":["anandamaya, hecha de dicha","vijnanamaya, hecha de saber","manomaya, hecha de mente","pranamaya, hecha de aliento"]}},{"id":"HINDUISM-s05-06","day":411,"d":4,"q":"a scholar has mastered the four Vedas, phonetics, grammar and ritual, but has not come to know the imperishable. in the Mundaka Upanishad's terms (1.1.4–5), what kind of knowledge does he have?","o":["para vidya, the higher knowledge","apara vidya, the lower knowledge","brahma vidya, knowledge of Brahman","atma vidya, knowing the self"],"a":1,"es":{"q":"un erudito domina los cuatro Vedas, la fonética, la gramática y el ritual, pero no ha llegado a conocer lo imperecedero. en los términos de la Mundaka Upanishad (1.1.4–5), ¿qué clase de conocimiento tiene?","o":["para vidya, el conocimiento superior","apara vidya, el conocimiento inferior","brahma vidya, el conocimiento de Brahman","atma vidya, el conocimiento del ser"]}}],[{"id":"HINDUISM-s06-01","day":428,"d":3,"q":"the last verse of the Shvetashvatara Upanishad (6.23) says its teachings shine for one who has the highest devotion (bhakti) to God, and the same devotion to whom?","o":["to one's mother and father","to a guest at one's door","to one's teacher (guru)","to the king of one's land"],"a":2,"es":{"q":"el último verso de la Shvetashvatara Upanishad (6.23) dice que sus enseñanzas brillan para quien tiene la más alta devoción (bhakti) a Dios, y la misma devoción ¿a quién?","o":["a su madre y a su padre","a un huésped en su puerta","a su maestro, el guru","al rey de su propia tierra"]}},{"id":"HINDUISM-s06-02","day":430,"d":3,"q":"how does Patanjali define yoga in Yoga Sutra 1.2?","o":["the stilling of the turnings of the mind","the union of the individual self with God","a steady and comfortable posture of the body","the regulation of the breath's in and out flow"],"a":0,"es":{"q":"¿cómo define Patanjali el yoga en el Yoga Sutra 1.2?","o":["el aquietamiento de los giros de la mente","la unión del ser individual con Dios","una postura del cuerpo firme y cómoda","el manejo del aliento al entrar y salir"]}},{"id":"HINDUISM-s06-03","day":449,"d":4,"q":"Yoga Sutra 2.5 defines avidya, the ignorance Patanjali names as the field of the other afflictions. what kind of error is it?","o":["not having studied the Vedas and the rules of correct ritual","forgetting the knowledge one gained in earlier births","doubting the teacher's words and the scripture's authority","mistaking the passing and the non-self for the lasting self"],"a":3,"es":{"q":"el Yoga Sutra 2.5 define avidya, la ignorancia que Patanjali nombra como el campo de las demás aflicciones. ¿qué clase de error es?","o":["no haber estudiado los Vedas ni las reglas del ritual correcto","olvidar el conocimiento que uno ganó en nacimientos anteriores","dudar de las palabras del maestro y de la autoridad de la escritura","tomar lo pasajero y lo que no es el ser por el ser duradero"]}},{"id":"HINDUISM-s06-04","day":440,"d":3,"q":"a coworker has just been caught lying to cheat a client. Yoga Sutra 1.33 pairs four attitudes with four kinds of people. which attitude does it pair with someone like this?","o":["karuna, compassion","upeksha, equanimity","maitri, friendliness","mudita, gladness"],"a":1,"es":{"q":"a un compañero de trabajo lo acaban de descubrir mintiendo para estafar a un cliente. el Yoga Sutra 1.33 empareja cuatro actitudes con cuatro tipos de personas. ¿qué actitud empareja con alguien así?","o":["karuna, compasión","upeksha, ecuanimidad","maitri, amabilidad","mudita, regocijo"]}},{"id":"HINDUISM-s06-05","day":473,"d":4,"q":"in book three of Patanjali's Yoga Sutras, how are the extraordinary powers (siddhis) to be regarded?","o":["as illusions with no reality, which only mislead the yogi","as the proof of samadhi that every yogi should seek","as powers to the outward mind but obstacles to samadhi","as gifts from Ishvara granted only to the devoted"],"a":2,"es":{"q":"en el libro tercero de los Yoga Sutras de Patanjali, ¿cómo hay que ver los poderes extraordinarios (siddhis)?","o":["como ilusiones sin realidad que solo confunden al yogui","como la prueba del samadhi que todo yogui debe buscar","como poderes afuera, pero estorbos para el samadhi","como dones de Ishvara concedidos solo a los devotos"]}},{"id":"HINDUISM-s06-06","day":509,"d":3,"q":"in the Bala Kanda of Valmiki's Ramayana, what happens when Rama takes up Shiva's great bow at King Janaka's court in Mithila?","o":["he strings it, draws it, and it breaks in two","he strings it and shoots through a spinning target","he cannot lift it until Vishvamitra blesses him","he lifts it but chooses not to string it in court"],"a":0,"es":{"q":"en el Bala Kanda del Ramayana de Valmiki, ¿qué pasa cuando Rama toma el gran arco de Shiva en la corte del rey Janaka, en Mithila?","o":["lo encuerda, lo tensa y el arco se parte en dos","lo encuerda y dispara a través de un blanco giratorio","no puede levantarlo hasta que Vishvamitra lo bendice","lo levanta, pero decide no encordarlo en la corte"]}}],[{"id":"HINDUISM-s07-01","day":519,"d":3,"q":"In Valmiki's Ramayana, why does King Dasharatha owe Kaikeyi two boons?","o":["he lost a wager to her during the horse sacrifice","she cured him of a long fever with forest herbs","she saved his life in the war against Shambara","she brought a rich dowry from the Kekaya kingdom"],"a":2,"es":{"q":"En el Ramayana de Valmiki, ¿por qué el rey Dasharatha le debe dos dones a Kaikeyi?","o":["perdió una apuesta con ella en el rito del caballo","lo curó de una larga fiebre con hierbas del bosque","le salvó la vida en la guerra contra Shambara","trajo una rica dote desde el reino de Kekaya"]}},{"id":"HINDUISM-s07-02","day":543,"d":3,"q":"In Valmiki's Ramayana, Dasharatha tells Kausalya that his death from grief for a son was foretold long ago. Who foretold it?","o":["the blind father of a young ascetic he shot by mistake","the sage Vasishtha, angered by the hasty coronation plan","Kaikeyi's father, the king of Kekaya, at her wedding","the sage Vishvamitra, when he took Rama to the forest"],"a":0,"es":{"q":"En el Ramayana de Valmiki, Dasharatha le dice a Kausalya que su muerte por el dolor de perder a un hijo fue anunciada hace mucho. ¿Quién la anunció?","o":["el padre ciego de un joven asceta al que mató por error","el sabio Vasishtha, molesto por la coronación apresurada","el padre de Kaikeyi, el rey de Kekaya, en la boda de ella","el sabio Vishvamitra, cuando llevó a Rama al bosque"]}},{"id":"HINDUISM-s07-03","day":549,"d":3,"q":"In Valmiki's Ramayana, why does Bharata set Rama's sandals on the throne at Nandigrama?","o":["to show the people that the throne was cursed","to govern only in Rama's name until he returns","to keep Kaikeyi from claiming the throne herself","to mark the year of mourning for Dasharatha"],"a":1,"es":{"q":"En el Ramayana de Valmiki, ¿por qué Bharata pone las sandalias de Rama sobre el trono en Nandigrama?","o":["para mostrarle a todo el pueblo que el trono estaba maldito","para gobernar solo en nombre de Rama hasta su regreso","para impedir que Kaikeyi reclamara el trono para sí","para marcar el año de luto por el rey Dasharatha"]}},{"id":"HINDUISM-s07-04","day":583,"d":3,"q":"In Valmiki's Ramayana, what do Rama and Sugriva walk around together to seal their friendship?","o":["a shrine to Shiva on Rishyamuka hill","the shore of Lake Pampa at sunrise","a banyan tree planted by the sage Matanga","a fire that Hanuman kindles between them"],"a":3,"es":{"q":"En el Ramayana de Valmiki, ¿alrededor de qué caminan juntos Rama y Sugriva para sellar su amistad?","o":["un santuario de Shiva en el monte Rishyamuka","la orilla del lago Pampa al amanecer","un baniano plantado por el sabio Matanga","un fuego que Hanuman enciende entre ellos"]}},{"id":"HINDUISM-s07-05","day":571,"d":4,"q":"A friend describes Lakshmana drawing a protective line around Sita's hut as a scene from Valmiki's Ramayana. What is accurate to tell them?","o":["Valmiki has it, but Ravana breaks the line by force","Valmiki has no such line; later tellings added it","Valmiki has it, but Rama is the one who draws the line","Valmiki has it, but only later, in the Uttara Kanda"],"a":1,"es":{"q":"Un amigo describe a Lakshmana trazando una línea protectora alrededor de la choza de Sita como una escena del Ramayana de Valmiki. ¿Qué es correcto decirle?","o":["Valmiki la incluye, pero Ravana la rompe por la fuerza","Valmiki no tiene esa línea; se añadió después","Valmiki la incluye, pero es Rama quien traza la línea","Valmiki la incluye, pero más tarde, en el Uttara Kanda"]}},{"id":"HINDUISM-s07-06","day":603,"d":3,"q":"In Valmiki's Kishkindha Kanda, why does Jambavan tell Hanuman the story of his birth on the shore?","o":["to rouse him to the leap by recalling his own power","to prove that Hanuman outranks Angada in the army","to warn him of a curse that will defeat him in Lanka","to explain why he must first ask Sugriva's leave"],"a":0,"es":{"q":"En el Kishkindha Kanda de Valmiki, ¿por qué Jambavan le cuenta a Hanuman la historia de su nacimiento en la orilla?","o":["para animarlo al salto recordándole su propio poder","para probar que Hanuman tiene más rango que Angada","para advertirle de una maldición que lo vencerá en Lanka","para explicarle por qué debe pedir permiso a Sugriva"]}}],[{"id":"HINDUISM-s08-01","day":636,"d":3,"q":"In Valmiki's Ramayana, who leads the building of the bridge to Lanka?","o":["Angada, the young son of Vali","Nala, the son of Vishvakarma","Jambavan, the king of the bears","Sushena, the father of Tara"],"a":1,"es":{"q":"En el Ramayana de Valmiki, ¿quién dirige la construcción del puente hacia Lanka?","o":["Angada, el joven hijo de Vali","Nala, el hijo de Vishvakarma","Jambavan, el rey de los osos","Sushena, el padre de Tara"]}},{"id":"HINDUISM-s08-02","day":655,"d":3,"q":"In the traditional (vulgate) text of Valmiki's Ramayana, which hymn does the sage Agastya teach Rama just before his final battle with Ravana?","o":["the Shiva Tandava, on Shiva's cosmic dance","the Vishnu Sahasranama, a thousand names","the Gayatri mantra, a Vedic verse to Savitr","the Aditya Hridayam, in praise of the sun"],"a":3,"es":{"q":"En el texto tradicional (vulgata) del Ramayana de Valmiki, ¿qué himno le enseña el sabio Agastya a Rama justo antes de su batalla final con Ravana?","o":["el Shiva Tandava, sobre la danza cósmica de Shiva","el Vishnu Sahasranama, los mil nombres de Vishnu","el mantra Gayatri, un verso védico a Savitr","el Aditya Hridayam, un himno en alabanza del sol"]}},{"id":"HINDUISM-s08-03","day":625,"d":4,"q":"In Valmiki's Sundara Kanda, after finding Sita, why does Hanuman decide to wreck Ravana's ashoka grove?","o":["to test the enemy's strength and be brought to Ravana","to carry out Sugriva's order to ruin all Ravana's gardens","to light a signal the army across the sea could see","to answer Sita's request to frighten her guards away"],"a":0,"es":{"q":"En el Sundara Kanda de Valmiki, después de encontrar a Sita, ¿por qué decide Hanuman destrozar el bosque de ashokas de Ravana?","o":["para medir la fuerza del enemigo y ser llevado ante Ravana","para cumplir la orden de Sugriva de arruinar los jardines","para encender una señal visible para el ejército al otro lado","para atender el pedido de Sita de asustar a sus guardias"]}},{"id":"HINDUISM-s08-04","day":638,"d":3,"q":"In Valmiki's Ramayana, when Vibhishana asks Rama for refuge and the camp argues, what vow does Rama state?","o":["to judge Vibhishana only after the war has been won","to accept him once he has fought against Ravana","to protect all who come once and say 'I am yours'","to shelter only those who share his own royal line"],"a":2,"es":{"q":"En el Ramayana de Valmiki, cuando Vibhishana le pide refugio a Rama y el campamento discute, ¿qué voto declara Rama?","o":["juzgar a Vibhishana solo después de ganar la guerra","aceptarlo una vez que haya luchado contra Ravana","proteger a quien venga una vez y diga 'soy tuyo'","dar refugio solo a quienes sean de su linaje real"]}},{"id":"HINDUISM-s08-05","day":657,"d":4,"q":"Two rival clans have fought for years, and one clan's leader has just been killed. A storyteller cites what Rama tells Vibhishana in Valmiki's Ramayana: enmity ends at death. What does that principle call for?","o":["leave his body unburied as a warning to allies","allow quiet rites for him, without any honors","honor him only once his clan admits its wrongs","give his body full funeral rites with honor"],"a":3,"es":{"q":"Dos clanes rivales llevan años peleando, y el líder de uno acaba de morir. Un narrador cita lo que Rama le dice a Vibhishana en el Ramayana de Valmiki: la enemistad termina con la muerte. ¿Qué pide ese principio?","o":["dejar su cuerpo sin sepultar como aviso a sus aliados","permitir ritos discretos, sin ningún honor para él","honrarlo solo cuando su clan admita sus culpas","darle a su cuerpo todos los ritos fúnebres con honor"]}},{"id":"HINDUISM-s08-06","day":629,"d":3,"q":"In Valmiki's Sundara Kanda, why is Hanuman horrified just after setting Lanka on fire?","o":["he fears the fire may have burned Sita herself","he sees that Vibhishana's house has caught fire","he recalls that Rama had forbidden any burning","he finds that his own tail cannot be put out"],"a":0,"es":{"q":"En el Sundara Kanda de Valmiki, ¿por qué Hanuman se horroriza justo después de incendiar Lanka?","o":["teme que el fuego haya quemado a la propia Sita","ve que la casa de Vibhishana ha empezado a arder","recuerda que Rama había prohibido quemar nada","descubre que no puede apagar su propia cola"]}}],[{"id":"HINDUISM-s09-01","day":697,"d":3,"q":"In the Mahabharata's frame story, who recites the epic at King Janamejaya's snake sacrifice?","o":["Sanjaya, the blind king's charioteer","Shuka, the son of the sage Vyasa","Vaishampayana, a disciple of Vyasa","Narada, the wandering divine sage"],"a":2,"es":{"q":"En el relato marco del Mahabharata, ¿quién recita la épica en el sacrificio de serpientes del rey Janamejaya?","o":["Sanjaya, el auriga del rey ciego","Shuka, el hijo del gran sabio Vyasa","Vaishampayana, discípulo de Vyasa","Narada, el sabio divino errante"]}},{"id":"HINDUISM-s09-02","day":713,"d":3,"q":"In the Mahabharata's Adi Parva, why does Devavrata come to be called Bhishma?","o":["for his fearsome duel with his teacher Parashurama","for his terrible vow to give up throne and marriage","for slaying the gandharva who had killed his brother","for the dread curse he laid on the house of Drupada"],"a":1,"es":{"q":"En el Adi Parva del Mahabharata, ¿por qué a Devavrata se le llega a llamar Bhishma?","o":["por su temible duelo contra su propio maestro Parashurama","por su terrible voto de dejar el trono y el matrimonio","por matar al gandharva que había matado a su hermano","por la maldición que lanzó sobre la casa de Drupada"]}},{"id":"HINDUISM-s09-03","day":722,"d":3,"q":"In the Mahabharata's Adi Parva, why is Dhritarashtra born blind?","o":["Shantanu's grief fell upon the unborn child","a sage cursed the Kuru line for Bhishma's vow","Gandhari's father laid a curse on the house","Ambika shut her eyes in fear when Vyasa came"],"a":3,"es":{"q":"En el Adi Parva del Mahabharata, ¿por qué Dhritarashtra nace ciego?","o":["el dolor de Shantanu cayó sobre el niño por nacer","un sabio maldijo el linaje kuru por el voto de Bhishma","el padre de Gandhari lanzó una maldición sobre la casa","Ambika cerró los ojos por miedo cuando llegó Vyasa"]}},{"id":"HINDUISM-s09-04","day":761,"d":3,"q":"In the Mahabharata's Sabha Parva, Krishna had promised Shishupala's mother to pardon how many of her son's offenses?","o":["100 offenses","1,000 offenses","108 offenses","500 offenses"],"a":0,"es":{"q":"En el Sabha Parva del Mahabharata, Krishna le había prometido a la madre de Shishupala perdonar ¿cuántas ofensas de su hijo?","o":["100 ofensas","1000 ofensas","108 ofensas","500 ofensas"]}},{"id":"HINDUISM-s09-05","day":786,"d":4,"q":"In the Vana Parva, Shiva gives Arjuna the Pashupata weapon with a warning about its use. If Arjuna later faced a weak, ordinary human foe, what would that warning require?","o":["use it only after first warning the foe","use it if the foe had struck the first blow","use it once Indra had given his own consent","hold it back and not hurl it at such a foe"],"a":3,"es":{"q":"En el Vana Parva, Shiva le da a Arjuna el arma Pashupata con una advertencia sobre su uso. Si Arjuna se enfrentara más tarde a un enemigo humano común y débil, ¿qué exigiría esa advertencia?","o":["usarla solo después de avisar al enemigo","usarla si el enemigo dio el primer golpe","usarla cuando Indra haya dado su permiso","contenerse y no lanzarla contra él"]}},{"id":"HINDUISM-s09-06","day":755,"d":3,"q":"In the Mahabharata's Sabha Parva, why must Jarasandha be dealt with before Yudhishthira can perform the Rajasuya?","o":["he holds many kings captive and blocks the rite","he has seized the Kuru capital at Hastinapura","he has stolen the horse meant for the great sacrifice","he has sworn to kill Yudhishthira at the rite"],"a":0,"es":{"q":"En el Sabha Parva del Mahabharata, ¿por qué hay que enfrentar a Jarasandha antes de que Yudhishthira pueda celebrar el Rajasuya?","o":["tiene presos a muchos reyes y bloquea el rito","se ha apoderado de la capital kuru, Hastinapura","ha robado el caballo destinado al gran sacrificio","ha jurado matar a Yudhishthira durante el rito"]}}],[{"id":"HINDUISM-s10-01","day":807,"d":4,"q":"During the Pandavas' year in disguise at King Virata's court (Mahabharata, Virata Parva), what role did Arjuna take?","o":["a cook and wrestler called Vallava","a dice-playing courtier called Kanka","a eunuch dance teacher, Brihannala","a keeper of the horses, Granthika"],"a":2,"es":{"q":"durante el año en que los Pandavas vivieron disfrazados en la corte del rey Virata (Mahabharata, Virata Parva), ¿qué papel asumió Arjuna?","o":["un cocinero y luchador llamado Vallava","un cortesano jugador de dados, Kanka","un eunuco maestro de danza, Brihannala","un cuidador de caballos, Granthika"]}},{"id":"HINDUISM-s10-02","day":806,"d":4,"q":"In the Mahabharata's episode of the Yaksha's questions, why does Yudhishthira ask that Nakula be revived rather than Bhima or Arjuna?","o":["so that Madri, like Kunti, would still have a living son","because Nakula was the youngest and most helpless brother","because Nakula had not drunk from the yaksha's lake","because the yaksha had offered to revive the weakest one"],"a":0,"es":{"q":"en el episodio de las preguntas del yaksha en el Mahabharata, ¿por qué Yudhishthira pide que reviva Nakula y no Bhima ni Arjuna?","o":["para que Madri, como Kunti, tuviera todavía un hijo vivo","porque Nakula era el hermano más joven y más indefenso","porque Nakula no había bebido del lago del yaksha","porque el yaksha había ofrecido revivir al más débil"]}},{"id":"HINDUISM-s10-03","day":835,"d":5,"q":"In the Drona Parva, why does Karna's use of Indra's Shakti dart against Ghatotkacha matter so much for Arjuna?","o":["the dart passed to Ashvatthama, who later turned it on Arjuna","it was a weapon made for rakshasas, with no power over men","using it broke Karna's oath and kept him off the field a day","it could be thrown once, so it was spent before he met Arjuna"],"a":3,"es":{"q":"en el Drona Parva, ¿por qué importa tanto para Arjuna que Karna use contra Ghatotkacha el dardo Shakti de Indra?","o":["el dardo pasó a Ashvatthama, que luego lo lanzó contra Arjuna","era un arma hecha para rakshasas, sin poder contra los hombres","usarlo rompió el juramento de Karna y lo alejó un día del campo","se podía lanzar una vez, así que se gastó antes de enfrentar a Arjuna"]}},{"id":"HINDUISM-s10-04","day":840,"d":5,"q":"In the Karna Parva, Krishna tells of the ascetic Kaushika, who truthfully showed robbers where travelers were hiding. Applying that teaching to a new case, how should a villager who truthfully tells a mob where a hunted innocent is hiding be judged?","o":["as right, since a true statement carries no fault in itself","as wrong, since truth is weighed by its effect on living beings","as blameless, since the guilt falls on the mob that acts on it","as right, provided the villager had taken a solemn vow of truth"],"a":1,"es":{"q":"en el Karna Parva, Krishna cuenta la historia del asceta Kaushika, que con verdad les mostró a unos ladrones dónde se escondían unos viajeros. Aplicando esa enseñanza a un caso nuevo, ¿cómo se juzga a un aldeano que con verdad le dice a una turba dónde se esconde un inocente perseguido?","o":["como correcto, porque una afirmación verdadera no tiene falta en sí","como incorrecto, porque la verdad se mide por su efecto en los seres","como libre de culpa, porque la culpa es de la turba que actúa","como correcto, si el aldeano había hecho un voto solemne de verdad"]}},{"id":"HINDUISM-s10-05","day":859,"d":4,"q":"In the Stri Parva of the Mahabharata, what does Gandhari's curse on Krishna foretell?","o":["that his brother Balarama would one day turn on him in battle","that he would lose his sight, as she had given up her own","that his own clan, the Vrishnis, would destroy one another","that his name would be forgotten in the land of the Kurus"],"a":2,"es":{"q":"en el Stri Parva del Mahabharata, ¿qué anuncia la maldición de Gandhari contra Krishna?","o":["que su hermano Balarama un día se volvería contra él en batalla","que perdería la vista, como ella había renunciado a la suya","que su propio clan, los Vrishnis, se destruiría a sí mismo","que su nombre sería olvidado en la tierra de los Kurus"]}},{"id":"HINDUISM-s10-06","day":872,"d":4,"q":"In the Ashvamedhika Parva, what does the half-golden mongoose claim about Yudhishthira's horse sacrifice?","o":["it is worth less than a poor family's gift of flour to a guest","it is void, since the horse was seized from a defeated king","it is flawed, since Krishna stayed away from the whole rite","it cannot wash away the sin of Drona's death by a lie"],"a":0,"es":{"q":"en el Ashvamedhika Parva, ¿qué afirma la mangosta medio dorada sobre el sacrificio del caballo de Yudhishthira?","o":["vale menos que la harina que una familia pobre dio a un huésped","es nulo, porque el caballo fue tomado de un rey vencido","tiene un defecto, porque Krishna no asistió a todo el rito","no puede lavar el pecado de la muerte de Drona por una mentira"]}}],[{"id":"HINDUISM-s11-01","day":890,"d":4,"q":"In the Bhagavata Purana, when Yashoda looks into the mouth of the child Krishna after he is accused of eating earth, what does she see?","o":["the serpent Kaliya coiled in a poisoned pool of the Yamuna","the whole universe, with the village of Vraja and herself in it","the city of Mathura, with King Kamsa seated on his throne","a lotus rising from his navel, with Brahma seated upon it"],"a":1,"es":{"q":"en el Bhagavata Purana, cuando Yashoda mira dentro de la boca del niño Krishna después de que lo acusan de comer tierra, ¿qué ve?","o":["la serpiente Kaliya enroscada en un estanque envenenado del Yamuna","el universo entero, con la aldea de Vraja y ella misma dentro","la ciudad de Mathura, con el rey Kamsa sentado en su trono","un loto que brota de su ombligo, con Brahma sentado sobre él"]}},{"id":"HINDUISM-s11-02","day":895,"d":4,"q":"In the Bhagavata Purana, why does the boy Krishna persuade the cowherds of Vraja to give up their yearly sacrifice to Indra?","o":["Indra had cursed the village with a drought that same year","King Kamsa had forbidden all offerings to the gods of rain","the rite required them to slaughter cattle from their herds","they live by their cows and the hill, so should honor those"],"a":3,"es":{"q":"en el Bhagavata Purana, ¿por qué el niño Krishna convence a los pastores de Vraja de dejar su sacrificio anual a Indra?","o":["Indra había maldecido a la aldea con una sequía ese mismo año","el rey Kamsa había prohibido toda ofrenda a los dioses de la lluvia","el rito los obligaba a sacrificar reses de sus propios rebaños","viven de sus vacas y de la colina, y deben honrar a estas"]}},{"id":"HINDUISM-s11-03","day":900,"d":5,"q":"In Bhagavata Purana 10.29, King Parikshit asks how the gopis, who loved Krishna as a lover rather than as the Absolute, could be set free. How does the sage Shuka answer?","o":["as Shishupala reached Krishna through hatred, any mind fixed on him attains him","the gopis' husbands had given them leave, so no dharma was broken on that night","the gopis had studied the Upanishads and already knew him as Brahman","Krishna had first given them knowledge of the Self through the sage Narada"],"a":0,"es":{"q":"en el Bhagavata Purana 10.29, el rey Parikshit pregunta cómo pudieron liberarse las gopis, que amaban a Krishna como amante y no como el Absoluto. ¿Qué responde el sabio Shuka?","o":["así como Shishupala llegó a Krishna por el odio, toda mente fija en él lo alcanza","los esposos de las gopis les habían dado permiso, así que no se rompió el dharma","las gopis habían estudiado las Upanishads y ya lo conocían como Brahman","Krishna antes les había dado el conocimiento del Ser por medio del sabio Narada"]}},{"id":"HINDUISM-s11-04","day":910,"d":4,"q":"In Tamil devotional tradition, how do the Alvars differ from the Nayanars?","o":["the Alvars sang in Sanskrit; the Nayanars sang in Tamil","the Alvars sang to Shiva; the Nayanars sang to Vishnu","the Alvars sang to Vishnu; the Nayanars sang to Shiva","the Alvars wrote in prose; the Nayanars wrote in verse"],"a":2,"es":{"q":"en la tradición devocional tamil, ¿en qué se diferencian los Alvars de los Nayanars?","o":["los Alvars cantaban en sánscrito; los Nayanars, en tamil","los Alvars le cantaban a Shiva; los Nayanars, a Vishnu","los Alvars le cantaban a Vishnu; los Nayanars, a Shiva","los Alvars escribían en prosa; los Nayanars, en verso"]}},{"id":"HINDUISM-s11-05","day":939,"d":4,"q":"At the World's Parliament of Religions in Chicago (1893), Vivekananda quoted a hymn likening humanity's paths to rivers that all flow into the sea. What did he use it to show?","o":["that each faith must purify itself as a river cleans its waters","that different paths, crooked or straight, all lead to one God","that faiths shift their course over the centuries, as rivers do","that pilgrimage to the sacred rivers is the oldest of all paths"],"a":1,"es":{"q":"en el Parlamento Mundial de las Religiones de Chicago (1893), Vivekananda citó un himno que compara los caminos de la humanidad con ríos que desembocan en el mar. ¿Qué quiso mostrar con él?","o":["que cada fe debe purificarse como un río limpia sus aguas","que caminos distintos, rectos o torcidos, llevan al mismo Dios","que las fes cambian su curso con los siglos, como los ríos","que la peregrinación a los ríos sagrados es el camino más antiguo"]}},{"id":"HINDUISM-s11-06","day":950,"d":5,"q":"A practitioner of self-enquiry notices worry about tomorrow rising during a sitting. Following Ramana Maharshi's Who Am I? (Nan Yar), what should they do with the thought?","o":["follow the worry to its end so that it exhausts itself","write the worry down and examine its meaning afterward","push the worry away by force and keep the body still","ask to whom it has come, and turn back to that 'I'"],"a":3,"es":{"q":"alguien que practica la indagación del Ser nota que, durante la sesión, le surge preocupación por el día de mañana. Según ¿Quién soy yo? (Nan Yar) de Ramana Maharshi, ¿qué debe hacer con ese pensamiento?","o":["seguir la preocupación hasta el final para que se agote","anotar la preocupación y examinar su sentido después","apartar la preocupación a la fuerza y quedarse quieto","preguntar a quién le vino y volver a ese 'yo'"]}}],[{"id":"HINDUISM-s12-01","day":963,"d":4,"q":"In Bhagavad Gita chapter 3, why does Krishna tell Arjuna that simply giving up action is no real way out?","o":["laying down action is a right kept for the priestly class","action is a debt to the ancestors that each son must repay","no one stays inactive even a moment; nature makes all act","the Vedas forbid a prince to withdraw to the forest"],"a":2,"es":{"q":"en el capítulo 3 del Bhagavad Gita, ¿por qué Krishna le dice a Arjuna que dejar de actuar no es una salida real?","o":["dejar la acción es un derecho reservado a la clase sacerdotal","la acción es una deuda con los ancestros que cada hijo debe pagar","nadie queda inactivo ni un momento; la naturaleza hace actuar a todos","los Vedas prohíben a un príncipe retirarse a vivir al bosque"]}},{"id":"HINDUISM-s12-02","day":970,"d":4,"q":"Bhagavad Gita 3.35 says it is better to do one's own duty, even imperfectly, than another's duty well. What Sanskrit term names that 'own duty'?","o":["svadharma","paradharma","rajadharma","apaddharma"],"a":0,"es":{"q":"el Bhagavad Gita 3.35 dice que es mejor cumplir el propio deber, aunque sea imperfectamente, que cumplir bien el deber de otro. ¿Qué término sánscrito nombra ese 'deber propio'?","o":["svadharma","paradharma","rajadharma","apaddharma"]}},{"id":"HINDUISM-s12-03","day":975,"d":4,"q":"Who composed the Gita Govinda, the twelfth-century Sanskrit poem on the love of Radha and Krishna?","o":["Vidyapati","Chandidas","Kalidasa","Jayadeva"],"a":3,"es":{"q":"¿quién compuso el Gita Govinda, el poema sánscrito del siglo XII sobre el amor de Radha y Krishna?","o":["Vidyapati","Chandidas","Kalidasa","Jayadeva"]}},{"id":"HINDUISM-s12-04","day":996,"d":5,"q":"The Vivekachudamani, traditionally attributed to Shankara, names the deer, elephant, moth, fish and bee, each destroyed through a single sense. What conclusion does it draw?","o":["each sense belongs to a deity and must be offered back to it","if one sense can destroy them, a person bound by five is worse off","animals follow their own nature, so humans must follow theirs","the senses weaken with age, so the practice must begin in youth"],"a":1,"es":{"q":"el Vivekachudamani, atribuido por la tradición a Shankara, nombra al venado, el elefante, la polilla, el pez y la abeja, cada uno destruido por un solo sentido. ¿Qué conclusión saca?","o":["cada sentido pertenece a una deidad y debe devolvérsele","si un sentido los destruye, quien está atado a los cinco está peor","los animales siguen su naturaleza; los humanos deben seguir la suya","los sentidos se debilitan con la edad; hay que empezar de joven"]}},{"id":"HINDUISM-s12-05","day":1002,"d":5,"q":"In the Ashtavakra Gita (3.2), what does the image of someone mistaking mother-of-pearl for silver explain?","o":["wealth is acceptable so long as it is given to the needy","the world is real, but the value we give it is invented","craving for the world arises from not knowing the Self","the Self wears away through contact, as silver does"],"a":2,"es":{"q":"en el Ashtavakra Gita (3.2), ¿qué explica la imagen de alguien que confunde el nácar con plata?","o":["la riqueza es aceptable si se da a los necesitados","el mundo es real, pero el valor que le damos es inventado","el deseo por el mundo surge de no conocer el Ser","el Ser se desgasta con el contacto, como la plata"]}},{"id":"HINDUISM-s12-06","day":1043,"d":4,"q":"In standard Sanskrit transliteration (IAST), a reader meets the name Gaṇeśa. What does the dot under the n tell them to do?","o":["lengthen the vowel that comes just before the n","nasalize the vowel before it with no full n sound","touch the tongue to the back of the upper teeth","curl the tongue back toward the roof of the mouth"],"a":3,"es":{"q":"en la transliteración estándar del sánscrito (IAST), alguien lee el nombre Gaṇeśa. ¿Qué le indica el punto debajo de la n?","o":["alargar la vocal que va justo antes de la n","nasalizar la vocal anterior sin una n completa","tocar con la lengua la parte de atrás de los dientes","curvar la lengua hacia atrás, hacia el paladar"]}}]]};
